(2462, NULL, 'Solesmes 1961', 'Stans beata Agatha', 1, 'an', '1', 'D', 'Andrew Hinkley', '', NULL, '\"(c4) STans(cd) be(dc)\\u00e1(d)ta(f) A(de)ga(dc)tha(c.) *(,) in(f_g) m\\u00e9(h)di(g)o(fe) c\\u00e1r(fg)ce(fv_ED)ris,(d.) (;) ex(d_h)p\\u00e1n(ixh_i)sis(h\') m\\u00e1(h)ni(gh)bus,(h.) (,) to(h)ta(g) men(fe)te(dc) (,) o(c_[uh:l-0.5mm]d)r\\u00e1(f_d/fg\'h)bat(fe) ad(gf) D\\u00f3(d)mi(cd)num :(d.) (:) D\\u00f3(h\')mi(g)ne(h) Je(j)su(jkj) Chri(h.)ste,(h.) (,) ma(hhg)g\\u00ed(fe)ster(fgf) bo(d.)ne,(d.) (;) gr\\u00e1(c)ti(df)as(f) a(fe)go(de) ti(dd)bi,(c.) (;) qui(f) me(gh) fe(h\')c\\u00ed(h)sti(g\') v\\u00edn(h)ce(gh)re(hd__) (,) tor(dg~)m\\u00e9n(f)ta(fe) car(d)n\\u00ed(fe)fi(dc)cum :(c.) (:) ju(c)be(df) me,(f\'_) D\\u00f3(f)mi(deDC\'d)ne,(dc..) (;) ad(ixf_g!hi) tu(hg)am(g_[uh:l]h) im(dg)mar(g)ce(g)sc\\u00ed(gh)bi(g)lem(fe~) gl\\u00f3(fg)ri(fe)am(c_[uh:l-0.5mm]d) (,) fe(cd)l\\u00ed(f\')ci(f)ter(fe) per(gh)v\\u00e9(fe)ni(d.)re.(d.) (::) <eu>E(h) u(h) o(g) u(f) a(gh) e.</eu>(gvFED.) (::)\"', NULL, NULL, NULL, 0, NULL),
(2463, NULL, 'Solesmes 1961', 'Laetentur caeli', 1, 'an', '4', 'A', 'Andrew Hinkley', '', NULL, '\"(c3) LAe(f)t\\u00e9n(e\')tur(f) cae(h_i)li,(ii) *(,) et(h\') ex(i)s\\u00fal(j)tet(ih) ter(i_[oh:h])ra(i.) (;) an(f)te(i) f\\u00e1(h\')ci(g)em(f) D\\u00f3(f\')mi(e)ni,(f_e) (,) qu\\u00f3(d_e)ni(f\')am(h) ve(f.)nit.(f.) (::) <eu>E(i) u(h) o(i) u(j) a(h) e.</eu>(f.) (::)\"', NULL, NULL, NULL, 0, NULL),
