(2557, NULL, 'Solesmes 1961', 'Misit Dominus (SS. Petri et Pauli)', 1, 'an', '7', 'c2', 'Andrew Hinkley', '', NULL, '\"(c3) MI(g)sit(h) D\\u00f3(i)mi(j)nus(i.) *(,) An(i_[uh:l]j)ge(h)lum(f) su(hh)um,(g.) (;) et(h) li(g\')be(h)r\\u00e1(ij)vit(i) me(h\'_) (,) de(f) ma(h\')nu(g) He(fe)r\\u00f3(f)dis,(e_[oh:h]d) (,) al(f!gwh)le(hvFE\'fwg_[oh:h]f)l\\u00fa(e.){ia}.(e.) (::) <eu>E(i) u(i) o(j) u(i) a(h) e.</eu>(ih..) (::)\"', NULL, NULL, NULL, 0, NULL),
(2558, NULL, 'Solesmes 1961', 'Si manseritis in me', 1, 'an', '7', 'a', 'Andrew Hinkley', '', NULL, '\"(c3) SI(e\') man(e)s\\u00e9(g\')ri(h)tis(i\') in(j) me,(i.) *(,) et(i) ver(h\')ba(j) me(l\')a(k) in(j\') vo(i)bis(ji~) m\\u00e1n(hg~)se(hi)rint,(i.) (;) quod(i\')c\\u00fam(j)que(i\') pe(h)ti(f)\\u00e9(h\')ri(h)tis,(g\'_[oh:h]) (,) fi(i)et(i) vo(hg)bis,(f.) (;) al(f)le(e)l\\u00fa(fhg){ia},(f.) (,) al(g_[uh:l]h)le(i)l\\u00fa(hg){ia},(f) al(g\')le(f)l\\u00fa(e.){ia}.(e.) (::) <eu>E(i) u(i) o(j) u(i) a(h) e.</eu>(gf..) (::)\"', NULL, NULL, NULL, 0, NULL),
(2559, NULL, 'Solesmes 1961', 'Tuam ipsius animam', 1, 'an', '6', 'F', 'Andrew Hinkley', '', NULL, '\"(c4) TU(f)am(gh) i(f)ps\\u00ed(fe)us(dc) \\u00e1(ixf!gwhg/hi)ni(h)mam(h.) *(,) <v>(</v>a(hj)it(h\') ad(h) Ma(g\')r\\u00ed(h)am(fg) S\\u00ed(f)me(e)on<v>)</v>(d_g) (;) per(g)trans(gf~)\\u00ed(g)bit(ghg) gl\\u00e1(f)di(f)us.(f.) (::) <eu>E(h) u(h) o(f) u(gh) a(g) e.</eu>(f.) (::)\"', NULL, NULL, NULL, 0, NULL),
(2560, NULL, 'Solesmes 1961', 'Te lucis ante terminum (In Epiphania Domini)', 1, 'hy', '8', NULL, 'Andrew Hinkley', '', NULL, '\"(c3) TE(d) lu(e)cis(fh) an(h)te(e) t\\u00e9r(f\')mi(d)num,(e\'_[oh:h]) (,) Re(h)rum(h\') Cre(f)\\u00e1(h)tor,(e) p\\u00f3(f)sci(de)mus,(e.) (;) Ut(h) pro(h\') tu(i)a(j) cle(h)m\\u00e9n(i\')ti(h)a,(f_e) (,) Sis(e) prae(e\')sul(d) et(c) cu(d)st\\u00f3(f)di(de)a.(e.) (::) \\r\\n2. Pro(d)cul(e) re(fh)c\\u00e9(h)dant(e) s\\u00f3(f\')mni(d)a,(e\'_[oh:h]) (,) Et(h) n\\u00f3(h\')cti(f)um(h) phan(e)t\\u00e1s(f)ma(de)ta :(e.) (;) Ho(h)st\\u00e9m(h\')que(i) no(j)strum(h) c\\u00f3m(i\')pri(h)me,(f_e) (,) Ne(e) pol(e\')lu(d)\\u00e1n(c)tur(d) c\\u00f3r(f)po(de)ra.(e.) (::) \\r\\n3. Prae(d)sta,(e) Pa(fh)ter(h) pi(e)\\u00eds(f\')si(d)me,(e\'_[oh:h]) (,) Pa(h)tr\\u00ed(h\')que(f) com(h)par(e) U(f)ni(de)ce,(e.) (;) Cum(h) Sp\\u00ed(h\')ri(i)tu(j) Pa(h)r\\u00e1(i\')cli(h)to,(f_e) (,) Re(e)gnans(e\') per(d) o(c)mne(d) sa\\u00e9(f)cu(de)lum.(e.) (::) \\r\\nA(efe)men.(de..) (::)\"', NULL, NULL, NULL, 0, NULL),
