v) Pa(h\')tri(h) sit(hg) gl\\u00f3(gh)ri(g)a,(g_[oh:h]f) (,) Et(h) F\\u00ed(h\')li(g)o,(fe) qu<e>i</e> {a}(d) m\\u00f3r(ef)tu(dc)is(cd..) (;) Sur(a)r\\u00e9(cd)xit,(d) ac(df) Pa(fd)r\\u00e1(e\')cli(d)to,(c\'_[oh:h]) (,) In(g) sae(g\')cu(f)l\\u00f3(ghg)rum(ed) sa\\u00e9(ef)cu(dc)la.(cd..) (::) \\r\\nA(ded)men.(cd..) (::)\"', NULL, NULL, NULL, 0, NULL),
