(3155, NULL, 'Solesmes 1961', 'Amicus meus', 1, 're', '8', NULL, 'Andrew Hinkley', NULL, NULL, '[[\"tex\",\"\\\\grechangedim{spacebeneathtext}{0.2 cm}{scalable}\",{}],[\"gabc\",\"(c4) A(g)m\\u00ed(g_[oh:h]f_[oh:h]//f.d!ewfED)cus(c_[uh:l-0.5mm]d) me(f_g)us(fg!hvhg\'/jh\'hg.) (;) * \\u00f3(j)scu(ji)li(hg) me(fg) tr\\u00e1(gh)di(g)dit(g.h!iwj/!jv_I_H\'_3/!iwj_i_/!h_iHG) si(g!hwihi)gno :(hg..) (:) Quem(g) o(f)scu(ghg\')l\\u00e1(h)tus(g\') f\\u00fa(g)e([oh:h{]g_e_2fv_[oh:}]ED\'e)ro,(e_[oh:h]d_[oh:h]) (,) i(f_0gh)pse(g) est,(h.) (;) te(gf)n\\u00e9(f.0h!iwjjv)te(j_kJ\'IH\'___iwjIH) e(gh!ivHG\'h)um :(hg..) (:) hoc(jv_jv_) ma(k_[uh:l]lK\'_[oh:h]J_[oh:h]I\'_[oh:h]jwk)lum(jkj\') fe(h)cit(g!hwji/jkj) si(jv_IHiv_[oh:h]H~G~)gnum,(hg..) (;) qui(f) per(ghg) \\u00f3(h)scu(g)lum(g.) (,) ad(g)im(g)pl\\u00e9(gh)vit(g) ho(g_[uh:l]hG\'E)mi(g)c\\u00ed(f/g\'h)di(fe)um.(dec./d!ewf_e_2fv_ED.) (:) * In(d)f\\u00e9(f_0gh)lix(g_0[uh:l]//hig\'/hggf.0) (,) prae(hf)ter(g)m\\u00ed(h!iwji/jkj)sit(h_g) pr\\u00e9(gh)ti(g)um(g/h\'i) s\\u00e1n(h)gui(h_g_2hv_GF\'g)nis,(gf..) (;) et(gh) in(g) fi(gh)ne(g.) l\\u00e1(gh)que(g)o(g\') se(g) sus(g.h!iwj/!jv_I_H\'_3/!iwj_i_/!h_iHG)p\\u00e9n(g!hwihi)dit.(hg..) (::) \\r\\n<sp>V/</sp>. Bo(ji)num(jkjijihhg) e(ij)rat(hi) e(g!hwi_[oh:h]h)i,(hg..) (;) si(g) na(fg)tus(g\') non(g) fu(g)\\u00eds(g)set(hi_[oh:h]HGhih) ho(ghf)mo(g_[uh:l]h) il(h!iwji/jkJ\'_4IH)le.(h_iHGhg..) (::) * In(d)f\\u00e9(f_0gh)lix.(g_0[uh:l]//hig\'/hggf.0) (::)\",{}]]', NULL, NULL, '1961 Ordo Hebdomadae Sanctae page 110', 0, NULL),
