nnes (Communauté Saint Martin/Solesmes)', 0, NULL),
(4685, NULL, 'Solesmes 1983', 'Christe qui splendor (Tempore Adventus post diem 16 decembris)', 1, 'hy', '4', NULL, 'Boris Maire', NULL, NULL, '\"(c4) Chris(f)te,(e) qui,(d) splen(e)dor(dc) et(de) di(e)es(e\'_) (,)\\r\\nnoc(g)tis(g!hwih) te(gf)n\\u00e9(g)bras(ghg) d\\u00e9(fe)te(de)gis,(e.) (;)\\r\\nlu(f)c\\u00eds(e)que(d) lum(e)en(dc) cr\\u00e9(dewf)de(d)ris,(d\'_) (,)\\r\\nlu(d)men(f) be(e)\\u00e1(g)tis(ghg) pr<sp>\'\\u00e6</sp>(fe)di(de)cans,(e.) (::)\"', 'Pre(f)cá(e)mur,(d) san(e)cte(dc) Dó(de)mi(e)ne,(e\'_) (,)\nhac(g) noc(g!hwih)te(gf) nos(g) cus(ghg)tó(fe)di(de)as;(e.) (;)\nsit(f) no(e)bis(d) in(e) te(dc) ré(dewf)qui(d)es,(d\'_) (,)\nqui(d)é(f)tas(e) ho(g)ras(ghg) trí(fe)bu(de)e.(e.) (::)\n  	 \nSom(f)no(e) si(d) dan(e)tur(dc) ó(de)cu(e)li,(e\'_) (,)\ncor(g) sem(g!hwih)per(gf) ad(g) te(ghg) ví(fe)gi(de)let;(e.) (;)\ntu(f)á(e)que(d) dex(e)tra(dc) pró(dewf)te(d)gas(d\'_) (,)\nfi(d)dé(f)les,(e) qui(g) te(ghg) dí(fe)li(de)gunt.(e.) (::)\n  	 \nDe(f)fén(e)sor(d) nos(e)ter,(dc) ás(de)pi(e)ce,(e\'_) (,)\nin(g)si(g!hwih)di(gf)án(g)tes(ghg) ré(fe)pri(de)me,(e.) (;)\ngu(f)bér(e)na(d) tu(e)os(dc) fá(dewf)mu(d)los,(d\'_) (,)\nquos(d) sán(f)gui(e)ne(g) mer(ghg)cá(fe)tus(de) es.(e.) (::)\n  	 \nSit(f) Chris(e)te,(d) rex(e) pi(dc)ís(de)si(e)me(e\'_) (,)\nti(g)bi(g!hwih) Pa(gf)trí(g)que(ghg) gló(fe)ri(de)a(e.) (;)\ncum(f) Spí(e)ri(d)tu(e) Pa(dc)rá(dewf)cli(d)to,(d\'_) (,)\nin(d) sem(f)pi(e)tér(g)na(ghg) sæ(fe)cu(de)la.(e.) (::)\n\nA(efe)men.(de..) (::)', '1. Christe, qui, splendor et dies,\\\\\nnoctis tenébras détegis,\\\\\nluc\\\'isque lumen créderis,\\\\\nlumen be\\\'atis pr\\\'\\ae dicans,\\\\\n\n2. Prec\\\'amur, sancte D\\\'omine,\\\\\nhac nocte nos cust\\\'odias ;\\\\\nsit nobis in te réquies,\\\\\nquiétas horas tr\\\'ibue.\\\\\n\n3. Somno si dantur \\\'oculi,\\\\\ncor semper ad te v\\\'igilet ;\\\\\ntu\\\'aque dextra pr\\\'otegas\\\\\nfidéles, qui te d\\\'iligunt.\\\\\n\n4. Defénsor noster, \\\'aspice,\\\\\ninsidi\\\'antes réprime,\\\\\ngubérna tuos f\\\'amulos,\\\\\nquos s\\\'anguine merc\\\'atus es.\\\\\n\n5. Sit, Christe, rex pi\\\'issime,\\\\\ntibi Patr\\\'ique gl\\\'oria,\\\\\ncum Sp\\\'iritu Par\\\'aclito,\\\\\nin sempitérna s\\\'\\ae cula.\\\\\n\nAmen.\\\\', 'Offici Completorium, Tempore Adventus post diem 16 decembris, Les Heures Grégoriennes (Communauté Saint Martin/Solesmes)', 0, NULL),
(4686, NULL, 'Solesmes 1983', 'Christe qui splendor (Tempore Quadragesimae hebdomadae II IV)', 1, 'hy', '2', NULL, 'Boris Maire', NULL, NULL, '\"(f3)CHris(g)te,(g) qui,(fe) splen(f)dor(g) et(h) di(g)es(f\'_) (,)\\r\\nNoc(f)tis(f) te(h)n\\u00e9(g)bras(e) d\\u00e9(f)te(h)gis,(g.) (;)\\r\\nLu(h)c\\u00eds(i)que(h) lu(g)men(f) cr\\u00e9(h)de(g)ris,(f\'_) (,)\\r\\nLu(g)men(g) be(fe)\\u00e1(f)tis(g) pr\\u01fd(h)di(g)cans,(f.) (::)\\r\\n\\r\\n2. Pre(g)c\\u00e1(g)mur,(fe) sanc(f)te(g) D\\u00f3(h)mi(g)ne,(f\'_) (,)\\r\\nHac(f) noc(f)te(h) nos(g) cus(e)t\\u00f3(f)di(h)as;(g.) (;)\\r\\nSit(h) no(i)bis(h) in(g) te(f) r\\u00e9(h)qui(g)es,(f\'_) (,)\\r\\nQui(g)\\u00e9(g)tas(fe) ho(f)ras(g) tr\\u00ed(h)bu(g)e.(f.) (::)\\r\\n\\r\\n3. Som(g)no(g) si(fe) dan(f)tur(g) \\u00f3(h)cu(g)li,(f\'_) (,)\\r\\nCor(f) sem(f)per(h) ad(g) te(e) v\\u00ed(f)gi(h)let;(g.) (;)\\r\\nTu(h)\\u00e1(i)que(h) dex(g)tra(f) pr\\u00f3(h)te(g)gas(f\'_) (,)\\r\\nFi(g)d\\u00e9(g)les,(fe) qui(f) te(g) d\\u00ed(h)li(g)gunt.(f.) (::)\\r\\n\\r\\n4. De(g)f\\u00e9n(g)sor(fe) nos(f)ter,(g) \\u00e1(h)spi(g)ce,(f\'_) (,)\\r\\nIn(f)si(f)di(h)\\u00e1n(g)tes(e) r\\u00e9(f)pri(h)me,(g.) (;)\\r\\nGu(h)b\\u00e9r(i)na(h) tu(g)os(f) f\\u00e1(h)mu(g)los,(f\'_) (,)\\r\\nQuos(g) s\\u00e1n(g)gui(fe)ne(f) mer(g)c\\u00e1(h)tus(g) es.(f.) (::)\\r\\n\\r\\n5. Sit,(g) Chris(g)te,(fe) rex(f) pi(g)\\u00eds(h)si(g)me,(f\'_) (,)\\r\\nTi(f)bi(f) Pa(h)tr\\u00ed(g)que(e) gl\\u00f3(f)ri(h)a,(g.) (;)\\r\\nCum(h) Sp\\u00ed(i)ri(h)tu(g) Pa(f)r\\u00e1(h)cli(g)to,(f\'_) (,)\\r\\nIn(g) sem(g)pi(fe)t\\u00e9r(f)na(g) s\\u01fd(h)cu(g)la.(f.) (::)\\r\\nA(ghg)men.(fg..) (::)\"', NULL, '', 'Offici Completorium, Tempore Quadragesimae hebdomadae II, IV, Les Heures Grégoriennes (Communauté Saint Martin/Solesmes)', 0, NULL),
