h) de(i)s\\u00e9r(i)to:(h_\') (,) u(hi)bi(h_\') ten(h)ta(h)v\\u00e9(h)runt(g) me(f) pa(g)tres(h) ve(gg)stri:(f.) (;) pro(f)ba(ec)v\\u00e9(ef)runt(f) et(f) vi(f)d\\u00e9(fg)runt(f_\') (,) \\u00f3(h)pe(gf)ra(h) me(gef)a.(f/ggf.) (::Z)\\r\\n\\r\\nQua(f)dra(e)g\\u00edn(f)ta(h) an(h)nis(h\') pr\\u00f3(h)xi(h)mus(i) fu(i)i(h_\') (,) ge(f)ne(h)ra(h)ti(i)\\u00f3(i)ni(h) hu(h)ic,(i\') (,) et(h) di(i)xi:(h_) (`) Sem(h)per(g) hi(f) er(g)rant(h) cor(gg)de.(f.) (;) I(f)psi(e) ve(f)ro(h) non(h) co(h)gno(h)v\\u00e9(h)runt(h) vi(h)as(i) me(i)as:(h_\') (,) qui(hi)bus(h_\') ju(h)r\\u00e1(h)vi(g) in(f) i(g)ra(h) me(gg)a:(f.) (;) Si(f) in(ec~)tro(e)\\u00ed(ef)bunt(f_\') (,) in(f) r\\u00e9(h)qui(gf)em(h) me(gef)am.\\u00bb(f/ggf.) (::Z)\\r\\n\\r\\nGl\\u00f3(f)ri(e)a(f) Pa(h)tri,(h) et(i) F\\u00ed(i)li(h)o,(h_\') (,) et(h) Spi(g)r\\u00ed(f)tu(g)i(h) San(gg)cto.(f.) (;) Si(f)cut(e) e(f)rat(h) in(h) prin(i)c\\u00ed(i)pi(h)o,(h_\') (,) et(gf~) nunc,(g) et(h) sem(gg)per,(f.) (;) et(f) in(ec~) s\\u01fd(ef)cu(f)la(f) s\\u00e6(f)cu(h)l\\u00f3(gf)rum.(h) A(gef)men.(f/ggf.) (::)\\r\\n\"', NULL, NULL, NULL, 0, NULL),
(8219, NULL, 'Solesmes 1961', 'Stat cultrix vigilans', 1, 'hy', '3', NULL, 'Mateusz Ciesiółka', NULL, NULL, '\"(c4) STat(e) cul(f)trix(ed) v\\u00ed(c)gi(e)lans(g.) (,) p\\u00e1u(g)pe(f\')ris(g) h\\u00f3r(h\')tu(f)li,(g.) (;) An(j)n\\u00f3(i)rum(hj) tr\\u00e9(i)de(h)cim(g.) (,) p\\u00e1r(j)vu(g\')la,(h) nil(e\') sci(f)ens,(g.) (:)\\r\\nPri(e)mas(g) do(fe)cta(d) pre(d)ces,(c.) (,) prae(e) s\\u00f3(d\')ci(e)is(f\') pi(d)a,(e.) (;) Sim(ce)plex,(g\') mi(g)tis(f) et(g) \\u00edn(h\')no(g)cens.(e.) (::)\\r\\n2. O(e)r\\u00e1n(f)tem(ed) M\\u00ed(c)cha(e)el(g.) (,)  An(g)ge(f\')lus(g) \\u00e9(h\')do(f)cet,(g.) (;) Quam(j) cla(i)rae(hj) p\\u00e1(i)ri(h)li(g.) (,) l\\u00fa(j)mi(g\')ne(h) v\\u00edr(e\')gi(f)nes,(g.) (:) Vir(e)t\\u00fa(g)tum(fe) m\\u00e9(d)ri(d)tis(c.) (,) con(e)sp\\u00ed(d\')cu(e)ae(f\') si(d)mul,(e.) (;) Cre(ce)bris(g\') al(g)l\\u00f3(f)qui(g)is(h\') fo(g)vent.(e.) (::)\\r\\n3. Dum(e) vo(f)ces(ed) s\\u00fa(c)pe(e)ras(g.) (,) \\u00e9x(g)ci(f\')pit,(g) \\u00e9x(h\')pa(f)vet :(g.) (;) Sed(j) fi(i)dens(hj) D\\u00f3(i)mi(h)no,(g.) (,) f\\u00f3r(j)ti(g\')or(h) in(e\') di(f)es,(g.) (:) Pa(e)rens(g) im(fe)p\\u00e9(d)ri(d)is,(c.) (,) pro(e) p\\u00e1(d\')tri(e)a(f\') li(d)bens,(e.) (;) Ca(ce)stam(g\') se(g) vo(f)vet(g) h\\u00f3(h\')sti(g)am.(e.) (::)\\r\\n4. Mox(e) dul(f)ces(ed) s\\u00f3(c)ci(e)as(g.) (,) et(g) p\\u00e1(f\')tri(g)am(h\') do(f)mum,(g.) (;) Et(j) cum(i) ma(hj)tre(i) pa(h)trem(g.) (,) jus(j)sa(g\') re(h)l\\u00edn(e\')que(f)re,(g.) (:) Mi(e)les(g) fa(fe)cta(d) De(d)i,(c.) (,) quo(e) vo(d\')cat(e) An(f\')ge(d)lus,(e.) (;) Fer(ce)tur(g\') nil(g) tr\\u00e9(f)pi(g)dans(h\') e(g)ques.(e.) (::)\\r\\n5. Qui(e) ter(f)ras(ed) st\\u00e1(c)tu(e)it,(g.) (,) gl\\u00f3(g)ri(f\')a(g) sit(h\') Pa(f)tri :(g.) (;) Qui(j) gen(i)tes(hj) r\\u00e9d(i)i(h)mit,(g.) (,) gl\\u00f3(j)ri(g\')a(h) F\\u00ed(e\')li(f)o :(g.) (:) San(e)cto(g) Spi(fe)r\\u00ed(d)tu(d)i(c.) (,) gl\\u00f3(e)ri(d\')a,(e) qui(f\') pi(d)as(e.) (;) Et(ce) for(g\')tes(g) \\u00e1(f)ni(g)mas(h\') fa(g)cit.(e.) (::)\\r\\nA(efe)men.(de..) (::)\"', NULL, NULL, NULL, 0, NULL),
