(9789, NULL, 'Solesmes 1934', 'Transeunte Domino', 1, 'an', '1', 'f', NULL, NULL, NULL, '\"(c4)TRan(d)se(dc)\\u00fan(f)te(g\') D\\u00f3(f)mi(gh)no,(h.) <v>\\\\greheightstar</v>(,) cla(h_g)m\\u00e1(ixi\')bat(h) c\\u00e6(g\')cus(g) ad(g) e(f_h)um:(g.) (;) Mi(g)se(g)r\\u00e9(e\')re(g) me(h_g)i,(f_g) (,) Fi(e_c)li(d_f) Da(e)vid.(d.) (::) E(h) u(h) o(g) u(f) a(gh) e.(gf..) (::)\\r\\n\"', NULL, NULL, NULL, 0, NULL),
