(15183, 'a03110', 'Antiphonale Monasticum 1934', 'Amen dico vobis quod uni', 1, 'an', '1', 'f', 'Dominique CROCHU', 'Mt 25, 40.34', NULL, '\"(c4)A(d)Men(dc~) di(f)co(g) vo(f_h)bis:(h_ggo) *(,) Quod(f_g) u(h)ni(g\') ex(f) m\\u00ed(g\')ni(f)mis(fe) me(f)is(d\') fe(c)c\\u00ed(df)stis,(f.) (,) mi(f_g)hi(e\') fe(f)c\\u00ed(d.)stis.(d.) (:) Ve(d)n\\u00ed(f\')te,(d) be(e\')ne(f)d\\u00ed(gh)cti(g) Pa(f_g)tris(e_f) me(d!ewf)i,(fc..) (;) pos(c)si(d)d\\u00e9(ffg)te(f\') pa(f)r\\u00e1(g)tum(f_e) vo(g)bis(fe) re(d_e)gnum(ddc.) (,) ab(e) i(f)n\\u00ed(g_e)ti(gh)o(fe) s\\u01fd(d)cu(cd)li.(d.) (::)\"', NULL, NULL, NULL, 0, NULL),
