(16681, NULL, 'Solesmes 2020', 'Verbum caro factum est', 1, 'an', '5', 'a2', NULL, NULL, NULL, '\"(c3)VEr(d)bum(f) ca(h)ro(gxg) fac(f)tum(gxgh) est(h) *(,) et(h) ha(h)bi(i)t\\u00e1(kj)vit(i) in(hi~) no(ih)bis;(f) (;) et(f) v\\u00ed(f)di(f)mus(f) gl\\u00f3(f)ri(e)am(d) e(ef~)ius,(f) (,) gl\\u00f3(fh)ri(efEDe)am(ed) (`) qua(d)si(e) U(f)ni(e)g\\u00e9(f)ni(ed)ti(e) a(fe) Pa(d)tre.(d) (::)\"', NULL, NULL, NULL, 0, NULL),
(16682, '001261', NULL, 'Adeptus est sedem', 1, 'an', '4', 'e', NULL, NULL, NULL, '\"(c4)A(f)dep(fe)tus(de) est(e) se(ef)dem(g) a(f)pos(fe)t\\u00f3(dc)li(d)ci(fgf) c\\u00fal(fe~)mi(de)nis(e) (;) qui(g@hwj) re(h)ti(g)a(f) car(g)n\\u00e1(fe)li(de)a(e) con(fe~)temp(d)se(e)rat(fg) ge(g)ni(ghg)t\\u00f3(e)ris.(e) (::)\"', NULL, NULL, 'Melody taken from Antiphonale Synopticum database, from ancient monastic antiphonary.', 0, NULL),
(16683, '005068', NULL, 'Supra pectum', 1, 'an', '2', 'd', NULL, NULL, NULL, '\"(f3)Su(f)pra(f) pec(e)tus(f) D\\u00f3(h)mi(g)ni(f) Ie(gvFE)su(f) re(hg)c\\u00fam(f)bens(f) e(e)van(h)g\\u00e9(i)li(h)i(g) flu(f)\\u00e9n(ef~)ta(e) (;) de(f) ip(e)so(f) sa(hhi)cro(h) Do(hi)mi(j)ni(i)ci(h) p\\u00e9c(i)to(hg)ris(fg) fon(fe~)te(g) po(hg)t\\u00e1(f)vit.(f) (::)\"', NULL, NULL, 'Melody taken from Antiphonale Synopticum database, from ancient monastic antiphonary.', 0, NULL),
(16684, NULL, 'Solesmes 1893', 'Quasi unum', 1, 'an', '3', 'a', NULL, NULL, NULL, '\"(c4)Qua(g)si(h) u(gh/jj)num(j) *() ex(j) pa(i)ra(j)d\\u00ed(k)si(j) flu(ji)m\\u00ed(hi)ni(h)bus,(g) (;) E(g)van(g)ge(g)l\\u00eds(h)ta(g) Io(hj)\\u00e1n(j)nes(j) (:) Ver(ji~)bi(h) De(ji)i(jk) gr\\u00e1(ji)ti(h)am(i) (;) in(ij) to(k)to(ji) ter(hi)r\\u00e1(hg)rum(gh) or(gf)be(g) dif(gf)f\\u00fa(e)dit.(e) (::)\"', NULL, NULL, 'Processionale Monasticum, 1893, p. 34', 0, NULL),
(16685, NULL, 'Solesmes 1983', 'Exsultet caelum laudibus', 1, 'hy', '1', NULL, NULL, NULL, NULL, '\"(c4)Ex(ddc)s\\u00fal(cf)tet(ed) c\\u00e6(dh)lum(h) l\\u00e1u(g\')di(f)bus,(e./ghd.) (;)\\r\\nre(f)s\\u00fal(ed)tet(de) ter(g)ra(g) g\\u00e1u(g\')di(f)is(ed/ffd.) (:)\\r\\nA(d)pos(d\')to(d)l\\u00f3(dh)rum(h) gl\\u00f3(h\')ri(g)am(hv_GF\'/gwhGFED.) (;)\\r\\nsa(e)cra(g\') ca(g)nunt(ghg/hvGF\'ED) sol(fe)l\\u00e9m(d)ni(cd)a.(d_eD\'Cd.) (::)\\r\\n\\r\\n2. Vos,(ddc) s\\u00e6(cf)cli(ed) jus(dh)ti(h) j\\u00fa(g\')di(f)ces,(e./ghd.) (;)\\r\\net(f) ve(ed)ra(de) mun(g)di(g) l\\u00fa(g\')mi(f)na,(ed/ffd.) (:)\\r\\nvo(d)tis(d\') pre(d)c\\u00e1(dh)mur(h) c\\u00f3r(h\')di(g)um:(hv_GF\'/gwhGFED.) (;)\\r\\nau(e)d\\u00ed(g\')te(g) pre(ghg/hvGF\'ED)ces(fe) s\\u00fap(d)pli(cd)cum.(d_eD\'Cd.) (::)\\r\\n\\r\\n3. Qui(ddc) c\\u00e6(cf)lum(ed) ver(dh)bo(h) cl\\u00e1u(g\')di(f)tis,(e./ghd.) (;)\\r\\nse(f)r\\u00e1s(ed)que(de) e(g)jus(g) s\\u00f3l(g\')vi(f)tis,(ed/ffd.) (:)\\r\\nnos(d) a(d\') pec(d)c\\u00e1(dh)tis(h) \\u00f3m(h\')ni(g)bus(hv_GF\'/gwhGFED.) (;)\\r\\ns\\u00f3l(e)vi(g\')te(g) jus(ghg/hvGF\'ED)su,(fe) qu\\u01fd(d)su(cd)mus.(d_eD\'Cd.) (::)\\r\\n\\r\\n4. Quo(ddc)rum(cf) pr\\u00e6(ed)c\\u00e9p(dh)to(h) s\\u00fab(g\')di(f)tur(e./ghd.) (;)\\r\\nsa(f)lus(ed) et(de) lan(g)guor(g) \\u00f3m(g\')ni(f)um,(ed/ffd.) (:)\\r\\nsa(d)n\\u00e1(d\')te(d) \\u00e6(dh)gros(h) m\\u00f3(h\')ri(g)bus,(hv_GF\'/gwhGFED.) (;)\\r\\nnos(e) red(g\')d\\u00e9n(g)tes(ghg/hvGF\'ED) vir(fe)t\\u00fa(d)ti(cd)bus:(d_eD\'Cd.) (::)\\r\\n\\r\\n5. Ut,(ddc) cum(cf) Ju(ed)dex(dh) ad(h)v\\u00e9(g\')ne(f)rit(e./ghd.) (;)\\r\\nchris(f)tus(ed) in(de) fi(g)ne(g) s\\u01fd(g\')cu(f)li,(ed/ffd.) (:)\\r\\nnos(d) sem(d\')pi(d)t\\u00e9r(dh)ni(h) g\\u00e1u(h\')di(g)i(hv_GF\'/gwhGFED.) (;)\\r\\nf\\u00e1(e)ci(g\')at(g) es(ghg/hvGF\'ED)se(fe) c\\u00f3m(d)po(cd)tes.(d_eD\'Cd.) (::)\\r\\n\\r\\n6. De(ddc)o(cf) sint(ed) lau(dh)des(h) gl\\u00f3(g\')ri(f)\\u00e6,(e./ghd.) (;)\\r\\nqui(f) dat(ed) nos(de) e(g)van(g)g\\u00e9(g\')li(f)cis(ed/ffd.) (:)