(16686, NULL, NULL, 'Isti sunt viri sancti quos elegit', 1, 'an', '4', 'e', NULL, NULL, NULL, '\"(c4)Is(e)ti(df) sunt(e) vi(ed)ri(cd) san(de)cti(d) *() quos(eg/hj) e(h)l\\u00e9(gh)git(h) D\\u00f3(h)mi(gf)nus(g) (,) in(gg) ca(d)ri(dc)t\\u00e1(dg)te(f) non(f>) fi(de)cta,(e) (;) et(edf) de(f)dit(fe) il(cd~)lis(d) gl\\u00f3(de)ri(d)am(dc) sem(f>)pi(fgf)t\\u00e9r(ede~)nam,(e) (,) quo(ed/fde/gd/fde/gh)rum(f) doc(gh)tr\\u00ed(g)na(f) ful(f>)get(e) ec(dg)cl\\u00e9(fe)si(de)a(e) (,) ut(edf) sol(fe) et(de~) lu(e)na.(e) (::) \"', NULL, NULL, 'Melody taken from Antiphonale Synopticum database, from the Worcester, Library of the Dean and Chapter (GB-WO) F. 160, Mitte 13.', 0, NULL),
(16687, NULL, 'Cisterciense 1955', 'Relictis retibus suis', 1, 'an', '1', 'g', NULL, NULL, NULL, '\"(c4)RE(dc)l\\u00edc(e)tis(f) r\\u00e9(gf)ti(d)bus(dc) su(dc)is,(c) *() se(f)c\\u00fa(gh)ti(g) sunt(g) D\\u00f3(h)mi(g)num(ef) Re(g)dem(fe~)pt\\u00f3(d)rem.(d) (::)\"', NULL, NULL, 'Melody taken from the Antiphonarii Cisterciensis, Pars Prima, 1955, p. 175', 0, NULL),
