(16710, NULL, 'Solesmes 1983', 'Aeterne lucis conditor', 1, 'hy', '4', NULL, 'carolus7', NULL, NULL, '\"(c4)\\u00c6(e)t\\u00e9r(c)ne(d) lu(f)cis(ef) C\\u00f3n(g)di(f)tor,(e\'_) (,) \\r\\nlux(e) i(c)pse(d) to(f)tus(ef) et(g) di(g)es,(g.) (;)\\r\\nno(g)ctem(f) nec(g) ul(h)lam(gf) s\\u00e9n(g)ti(f)ens(e\'_) (,)\\r\\nna(e)tu(c)ra(d) lu(f)cis(ef) p\\u00e9r(g)pe(f)tis.(e.) (::) \"', '2. Iam(e) ce(c)dit(d) pal(f)lens(ef) pró(g)xi(f)mo(e\'_) (,)\ndi(e)é(c)i(d) nox(f) ad(ef)vén(g)tu(g)i,(g.) (;)\nob(g)tún(f)dens(g) lu(h)men(gf) sí(g)de(f)rum(e\'_) (,)\na(e)dest(c) et(d) cla(f)rus(ef) lú(g)ci(f)fer.(e.) (::) \n\n3. Iam(e) stra(c)tis(d) læ(f)ti(ef) súr(g)gi(f)mus(e\'_) (,)\ngra(e)tes(c) ca(d)nén(f)tes(ef) et(g) tu(g)as,(g.) (;)\nquod(g) cæ(f)cam(g) no(h)ctem(gf) ví(g)ce(f)rit(e\'_) (,)\nre(e)vé(c)ctans(d) rur(f)sus(ef) sol(g) di(f)em.(e.) (::) \n\n4. Te(e) nunc,(c) ne(d) car(f)nis(ef) gáu(g)di(f)a(e\'_) (,)\nblan(e)dis(c) su(d)bré(f)pant(ef) ǽ(g)sti(g)bus,(g.) (;)\ndo(g)lis(f) ne(g) ce(h)dat(gf) sǽ(g)cu(f)li(e\'_) (,)\nmens(e) no(c)stra,(d) san(f)cte,(ef)  q()ǽ(g)su(f)mus.(e.) (::) \n\n5. I(e)ra(c) ne(d) ri(f)xas(ef) pró(g)vo(f)cet,(e\'_) (,)\ngu(e)lam(c) ne(d) ven(f)ter(ef) ín(g)ci(g)tet,(g.) (;)\no(g)pum(f) per(g)vér(h)tat(gf) ne(g) fa(f)mis,(e\'_) (,)\ntur(e)pis(c) ne(d) lu(f)xus(ef) óc(g)cu(f)pet.(e.) (::) \n\n6. Sed(e) fir(c)ma(d) men(f)te(ef) só(g)bri(f)i,(e\'_) (,)\nca(e)sto(c) ma(d)nén(f)tes(ef) cór(g)po(g)re(g.) (;)\nto(g)tum(f) fi(g)dé(h)li(gf) spí(g)ri(f)tu(e\'_) (,)\nChri(e)sto(c) du(d)cá(f)mus(ef) hunc(g) di(f)em.(e.) (::) \n\n7. Præ(e)sta,(c) Pa(d)ter(f) pi(ef)ís(g)si(f)me,(e\'_) (,)\nPa(e)trí(c)que(d) com(f)par(ef) U(g)ni(g)ce,(g.) (;)\ncum(g) Spí(f)ri(g)tu(h) Pa(gf)rá(g)cli(f)to(e\'_) (,)\nre(e)gnans(c) per(d) om(f)ne(ef) sǽ(g)cu(f)lum.(e.) (::)\n', NULL, NULL, 0, NULL),
(16711, NULL, 'Solesmes 2019', 'Dulce fit nobis', 1, 'hy', '8', NULL, NULL, NULL, NULL, '\"(c4) DUl(h)ce(g) fit(hi) no(ji)bis(h) (,) me(i)mo(j)r\\u00e1(h)re(i) par(h)vum(g) (;) N\\u00e1(ef)za(e)r\\u00e6(d) tec(dh)tum(h) (,) te(h)nu(g)\\u00e9m(h)que(i) cul(ij)tum;(g) (:) \\u00e9x(i)pe(k)dit(j) Ie(ih)su(g) (,) t\\u00e1(d)ci(e)tam(f) re(g)f\\u00e9r(gh)re(h) (,) c\\u00e1r(g)mi(e)ne(f) vi(g)tam.(g) (::)\\r\\n\\r\\n2. Ar(h)te(g) qua(hi) Io(ji)seph(h) (,) h\\u00fa(i)mi(j)l<i>i</i> ex(h) co(i)l\\u00e9n(h)dus,(g) (;) \\u00e1b(ef)di(e)to(d) Ie(dh)sus(h) (,) iu(h)ve(g)n\\u00e9s(h)cit(i) \\u00e6(ij)vo,(g) (:) se(i)que(k) fa(j)br\\u00ed(ih)lis(g) (,) s\\u00f3(d)ci(e)um(f) la(g)b\\u00f3(gh)ris(h) (,) \\u00e1(g)di(e)cit(f)  ul(g)tro.(g) (::)\\r\\n\\r\\n3. As(h)si(g)det(hi) na(ji)to(h) (,) pi(i)a(j) ma(h)ter(i) al(h)mo,(g) (;) \\u00e1s(ef)si(e)det(d) spon(dh)so(h) (,) bo(h)na(g) nup(h)ta,(i) fe(ij)lix(g) (:) si(i) po(k)test(j) cu(ih)ras(g) (,) re(d)le(e)v\\u00e1(f)re(g) las(gh)sis(h) (,) m\\u00fa(g)ne(e)r<i>e</i> a(f)m\\u00ed(g)co.(g) (::)\\r\\n\\r\\n4. O(h) ne(g)qu<i>e</i> ex(hi)p\\u00e9r(ji)tes(h) (,) \\u00f3(i)pe(j)r<i>\\u00e6</i> et(h) la(i)b\\u00f3(h)ris,(g) (;) nec(ef)ma(e)l<i>i</i> i(d)gn\\u00e1(dh)ri,(h) (,) m\\u00ed(h)se(g)ros(h) iu(i)v\\u00e1(ij)te;(g) (:) quot(i)quot(k) im(j)pl\\u00f3(ih)rant(g) (,) c\\u00f3(d)lu(e)men,(f) be(g)n\\u00ed(gh)gno(h) (,) c\\u00e9r(g)ni(e)te(f) vul(g)tu.(g) (::)\\r\\n\\r\\n5. Sit(h) ti(g)bi,(hi) Ie(ji)su,(h) (,) de(i)cus(j) at(h)que(i) vir(h)tus,(g) (;) san(ef)cta(e) qui(d) vi(dh)t\\u00e6(h) (,) do(h)cu(g)m\\u00e9n(h)ta(i) pr\\u00e6(ij)bes,(g) (:) qui(i)que(k) cum(j) sum(ih)mo(g) (,) Ge(d)ni(e)t\\u00f3(f)r<i>e</i> et(g) al(gh)mo(h) (,) Fl\\u00e1(g)mi(e)ne(f) re(g)gnas.(g) (::) A(ghg)men.(fg) (::)\"', NULL, NULL, 'Source: Liber Hymnarius, 2019 edition., p. 28', 0, NULL),
(16712, NULL, 'Solesmes 1983', 'Sator princépsque témporum', 1, 'hy', '1', NULL, 'carolus7', NULL, NULL, '\"(c4)SA(f)tor(f) prin(g)c\\u00e9ps(h)que(f) t\\u00e9m(g)po(f)rum,(e_) (,)\\r\\ncla(g)rum(f) di(f)es(e) la(d)b\\u00f3(f)ri(g)bus(f.) (;)\\r\\nnoc(f)t\\u00e9m(f)que(g) qui(h) so(f)p\\u00f3(g)ri(f)bus(e) (,)\\r\\nfi(g)xo(f) di(f)st\\u00edn(e)guis(d) \\u00f3r(f)di(e)ne.(d.) (::)\"', '2. Men(f)tem(f) tu(g) cas(h)ta(f) dí(g)ri(f)ge,(e_) (,)\nobs(g)cú(f)ra(f) ne(e) si(d)lén(f)ti(g)a(f.) (;)\nad(f) di(f)ra(g) cor(h)dis(f) vúl(g)ne(f)ra(e) (,)\nte(g)lis(f) pa(f)tés(e)cant(d) ín(f)vi(e)di.(d.) (::)\n\n3. Va(f)cent(f) ar(g)dó(h)re(f) péc(g)to(f)ra,(e_) (,)\nfa(g)ces(f) nec(f) ul(e)la(d) pér(f)fe(g)rant,(f.) (;)\nquæ(f) nostr<i>o</i>(f) hæ(g)rén(h)tes(f) sén(g)su(f)i(e) (,)\nmen(g)tis(f) vi(f)gó(e)rem(d) sáu(f)ci(e)ent.(d.) (::)\n\n4. Præ(f)sta,(f) Pa(g)ter(h) pi(f)ís(g)si(f)me,(e_) (,)\nPa(g)trí(f)que(f) com(e)par(d) U(f)ni(g)ce,(f.) (;)\ncum(f) Spí(f)ri(g)tu(h) Pa(f)rá(g)cli(f)to(e) (,)\nre(g)gnans(f) per(f) om(e)ne(d) sǽ(f)cu(e)lum.(d.) (::)\n\nA(ded)men.(cd..) (::)\n', NULL, NULL, 0, NULL),
