(16743, '', 'Solesmes', 'Agnus VIII', 1, 'ky', '6', NULL, 'BruceL', NULL, NULL, '\"annotation: VI;\\r\\n%%\\r\\n(c4) A(fggf)gnus(gh) De(fgf___)i,(f.) *(,) qui(f) tol(fd~)lis(dc) pec(d)c\\u00e1(c)ta(df) mun(fgf___)di :(f.) (;) mi(f)se(gh)r\\u00e9(h)re(ixgiHGh) no(fgf___)bis.(f.) (::)\\r\\nA(f)gnus(hj) De(jvHGj)i,(j.) *(,) qui(j) tol(hgh)lis(f) pec(g)c\\u00e1(f)ta(gh) mun(fgf___)di :(f.) (;) mi(f)se(gh)r\\u00e9(h)re(ixgiHGh) no(fgf___)bis.(f.) (::)\\r\\nA(fggf)gnus(gh) De(fgf___)i,(f.) *(,) qui(f/) tol(fd~)lis(dc) pec(d)c\\u00e1(c)ta(df) mun(fgf___)di :(f.) (;) do(f)na(gh) no(h)bis(ixgiHGh) pa(fgf___)cem.(f.) (::)\\r\\n\\r\\n\"', NULL, NULL, NULL, 0, NULL),
(16744, NULL, 'Solesmes 1934', 'Salvete flores', 1, 'hy', '8', NULL, 'Jakub Jelínek', NULL, NULL, '\"(c4)\\r\\nSAl(g)v\\u00e9(g\')te(f) flo(e)res(d) M\\u00e1r(fhg)ty(fg)rum,(g.) (,) \\r\\nQuos(h!iwji) lu(h)cis(g) i(h)ps<i>o</i>() in(ig) l\\u00ed(h\')mi(g)ne(f.) (;)      \\r\\nChri(f)st<i>i</i> {i}n(g\')se(f)c\\u00fa(g)tor(h) s\\u00fa(j\')stu(g)lit,(hih\'_15) (,)      \\r\\nCeu(h) tur(h\')bo(g) na(e)sc\\u00e9n(f)tes(hg) ro(fg)sas.(g.) (::)\\r\\n\"', '2. Vos(g) pri(g\')ma(f) Chri(e)sti(d) ví(fhg)cti(fg)ma,(g.) (,) \nGrex(h!iwji) im(h)mo(g)la(h)tó(ig)rum(h\') te(g)ner:(f.) (;) \nA(f)r<i>am</i> {a}n(g\')te(f) i(g)psam(h) sím(j\')pli(g)ces,(hih\'_15) (,) \nPal(h)m<i>a</i> {e}t(h\') co(g)ró(e)nis(f) lú(hg)di(fg)tis.(g.) (::)       \n\n3. Gló(g)ri(g\')a(f) ti(e)bi(d) Dó(fhg)mi(fg)ne,(g.) (,)\nQui(h!iwji) na(h)tus(g) es(h) de(ig) Vír(h\')gi(g)ne,(f.) (;) \nCum(f) Pa(g\')tr<i>e</i> {e}t(f) San(g)cto(h) Spí(j\')ri(g)tu,(hih\'_15) (,)      \nIn(h) sem(h\')pi(g)tér(e)na(f) sǽ(hg)cu(fg)la.(g.) (::)\n\nA(ghg)men.(fg..) (::)', NULL, NULL, 0, NULL),
(16745, NULL, 'Solesmes 1983', 'Vita sanctorum', 1, 'hy', '1', NULL, 'carolus7', '', NULL, '\"(c4)Vi(d_)ta(c) sanc(d)t\\u00f3(fg)rum,(f_\') (,) vi(g)a,(h) spes(g) sa(f)l\\u00fas(g.)que,(h.) (;)\\r\\nChris(gh)te,(i) lar(h)g\\u00ed(gf)tor(e\'_) (,) pro(d)bi(f)t\\u00e1(e)tis(f) at(d.)que(c.) (:)\\r\\nc\\u00f3n(d_)di(c)tor(d) pa(fg)cis,(f\'_) (,) ti(g)bi(h) vo(g)ce,(f) sen(e.)su(d.) (,)\\r\\np\\u00e1n(f_)gi(e)mus(f) hym(dc)num:(d.) (::)\"', '2. Cu(d_)ius(c) est(d) vir(fg)tus(f_\') (,) ma(g)ni(h)fés(g)ta(f) to(g.)tum(h.) (;)\nquod(gh) pi(i)i(h) pos(gf)sunt,(e\'_) (,) quod(d) ha(f)bent,(e) quod(f) o(d.)re,(c.) (:)\ncor(d_)de(c) vel(d) fac(fg)tis(f\'_) (,) cú(g)pi(h)unt,(g) a(f)mó(e.)ris(d.) (,)\ni(f_)gne(e) fla(f)grán(dc)tes.(d.) (::)\n\n3. Tém(d_)po(c)rum(d) pa(fg)cem,(f_\') (,) fí(g)de(h)i(g) te(f)nó(g.)rem,(h.) (;)\nlán(gh)gui(i)dis(h) cu(gf)ram(e\'_) (,) ve(d)ni(f)ám(e)que(f) lap(d.)sis,(c.) (:)\nóm(d_)ni(c)bus(d) præ(fg)sta(f\'_) (,) pá(g)ri(h)ter(g) be(f)á(e.)tæ(d.) (,)\nmú(f_)ne(e)ra(f) vi(dc)tæ.(d.) (::)\n\n4. Æ(d_)qua(c) laus(d) sum(fg)mum(f_\') (,) cé(g)le(h)bret(g) Pa(f)rén(g.)tem(h.) (;)\nte(gh)que,(i) Sal(h)vá(gf)tor,(e\'_) (,) pi(d)e(f) rex,(e) per(f) æ(d.)vum;(c.) (:)\nSpí(d_)ri(c)tus(d) Sanc(fg)ti(f\'_) (,) ré(g)so(h)net(g) per(f) om(e.)nem(d.) (,)\ngló(f_)ri(e)a(f) mun(dc)dum.(d.) (::) A(d_)men.(c)\n', NULL, 'Officium lectionis (diurno tempore)', 0, NULL),
(16746, NULL, 'Solesmes 1983', 'Sol, ecce, lentus', 1, 'hy', '1', NULL, 'carolus7', NULL, NULL, '\"(c4)Sol,(f) ec(f)ce,(g) len(h)tus(f) \\u00f3c(g)ci(f)dens(e\'_) (,)\\r\\nmon(g)tes(f) et(f) ar(e)<i>va</i>() et(d) \\u01fd(f)quo(g)ra(f.) (;)\\r\\nm\\u00e6s(f)tus(f) re(g)l\\u00edn(h)quit,(f) \\u00edn(g)no(f)vat(e\'_) (,)\\r\\nsed(g) lu(f)cis(f) o(e)men(d) cr\\u00e1s(f)ti(e)n\\u00e6,(d.) (::)\"', '2. Mi(f)rán(f)ti(g)bus(h) mor(f)tá(g)li(f)bus(e\'_) (,)\nsic(g) te,(f) Cre(f)á(e)tor(d) pró(f)vi(g)de,(f.) (;)\nle(f)ges(f) vi(g)cés(h)que(f) tém(g)po(f)rum(e\'_) (,)\num(g)bris(f) de(f)dís(e)<i>se</i>() et(d) lú(f)mi(e)ni.(d.) (::)\n\n3. Ac(f) dum,(f) té(g)ne(h)bris(f) ǽ(g)the(f)ra(e\'_) (,)\nsi(g)lén(f)ti(f)o(e) pre(d)mén(f)ti(g)bus,(f.) (;)\nvi(f)gor(f) la(g)bó(h)rum(f) dé(g)fi(f)cit,(e\'_) (,)\nqui(g)es(f) cu(f)pí(e)ta(d) quǽ(f)ri(e)tur,(d.) (::)\n\n4. Spe(f) nos(f) fi(g)dé(h)que(f) dí(g)vi(f)tes(e\'_) (,)\ntu(g)i(f) be(f)á(e)mur(d) lú(f)mi(g)ne(f.) (;)\nVer(f)bi,(f) quod(g) est(h) a(f) sǽ(g)cu(f)lis(e\'_) (,)\nsplen(g)dor(f) pa(f)tér(e)næ(d) gló(f)ri(e)æ.(d.) (::)\n\n5. Est(f) il(f)le(g) sol(h) qui(f) né(g)sci(f)at(e\'_) (,)\nor(g)tum(f) vel(f) um(e)quam(d) vés(f)pe(g)rum;(f.) (;)\nquo(f) ter(f)ra(g) ges(h)tit(f) cón(g)te(f)gi,(e\'_) (,)\nquo(g) cæ(f)<i>li</i>() in(f) æ(e)vum(d) iú(f)bi(e)lant.(d.) (::)\n\n6. Hac(f) nos(f) se(g)ré(h)na(f) pér(g)pe(f)tim(e\'_) (,)\nda(g) lu(f)ce(f) tan(e)dem(d) pér(f)fru(g)i,(f.) (;)\ncum(f) Na(f)<i>to</i>() et(g) al(h)mo(f) Spí(g)ri(f)tu(e\'_) (,)\nti(g)bi(f) no(f)ván(e)tes(d) cán(f)ti(e)ca.(d.) (::)\n', NULL, 'Feria IV ad Vesperas', 0, NULL);
