(16747, NULL, 'Solesmes 1983', 'Deus qui claro lúmine', 1, 'hy', '1', NULL, 'carolus7', NULL, NULL, '\"(c4)DE(f)us,(f) qui(g) cla(h)ro(f) l\\u00fa(g)mi(f)ne(e\'_) (,)\\r\\ndi(g)em(f) fe(f)c\\u00ed(e)sti,(d) D\\u00f3(f)mi(g)ne,(f.) (;)\\r\\ntu(f)am(f) ro(g)g\\u00e1(h)mus(f) gl\\u00f3(g)ri(f)am(e\'_) (,)\\r\\ndum(g) pro(f)nus(f) di(e)es(d) v\\u00f3l(f)vi(e)tur.(d.) \\r\\n\\r\\n2.(::) Jam(f) sol(f) ur(g)g\\u00e9n(h)te(f) v\\u00e9(g)spe(f)ro(e\'_) (,) \\r\\noc(g)c\\u00e1(f)sum(f) su(e)um(d) gr\\u00e1(f)di(g)tur,(f.) (;)\\r\\nmun(f)dum(f) con(g)cl\\u00fa(h)dens(f) t\\u00e9(g)ne(f)bris,(e\'_) (,)\\r\\nsu(g)um(f) ob(f)s\\u00e9r(e)vans(d) \\u00f3r(f)di(e)nem.(d.) \\r\\n\\r\\n3.(::) Tu(f) ve(f)r<i>o</i>,() ex(g)c\\u00e9l(h)se(f) D\\u00f3(g)mi(f)ne,(e\'_) (,)\\r\\npre(g)c\\u00e1n(f)tes(f) tu(e)os(d) f\\u00e1(f)mu(g)los(f.) (;)\\r\\ndi(f)\\u00far(f)no(g) las(h)sos(f) \\u00f3(g)pe(f)re(e\'_) (,)\\r\\nne(g) si(f)nas(f) um(e)bris(d) \\u00f3p(f)pri(e)mi.(d.) \\r\\n\\r\\n4.(::) Ut(f) non(f) fu(g)sc\\u00e1(h)tis(f) m\\u00e9n(g)ti(f)bus(e\'_) (,)\\r\\ndi(g)es(f) ab(f)sc\\u00e9(e)dat(d) s\\u01fd(f)cu(g)li,(f.) (;)\\r\\nsed(f) tu(f)a(g) te(h)cti(f) gr\\u00e1(g)ti(f)a(e\'_) (,)\\r\\ncer(g)n\\u00e1(f)mus(f) lu(e)cem(d) pr\\u00f3(f)spe(e)ram.(d.) \\r\\n\\r\\n5.(::) Pr\\u00e6(f)sta,(f) Pa(g)ter(h) pi(f)\\u00eds(g)si(f)me,(e\'_) (,)\\r\\nPa(g)tr\\u00ed(f)que(f) com(e)par(d) U(f)ni(g)ce,(f.) (;)\\r\\ncum(f) Sp\\u00ed(f)ri(g)tu(h) Pa(f)r\\u00e1(g)cli(f)to(e\'_) (,)\\r\\nre(g)gnans(f) per(f) om(e)ne(d) s\\u01fd(f)cu(e)lum.(d.) (::)\\r\\n\"', '', NULL, 'Feria V ad Vesperas', 0, NULL),
(16748, NULL, 'Solesmes 1983', 'Deus qui caeli lumen es', 1, 'hy', '4', NULL, 'carolus7', NULL, NULL, '\"(c4)DE(e)us,(c) qui(d) c\\u00e6(f)li(ef) lu(g)men(f) es(e\'_) (,)\\r\\nsa(e)t\\u00f3r(c)que(d) lu(f)cis,(ef) qui(g) po(g)lum(g.) (;)\\r\\npa(g)t\\u00e9r(f)no(g) ful(h)tum(gf) br\\u00e1(g)chi(f)o(e\'_) (,)\\r\\npr\\u00e6(e)cl\\u00e1(c)ra(d) pan(f)dis(ef) d\\u00e9x(g)te(f)ra,(e.) (::)\"', '2. Au(e)ró(c)ra(d) stel(f)las(ef) iam(g) te(f)git(e\'_) (,)\nru(e)brum(c) sus(d)tól(f)lens(ef) gúr(g)gi(g)tem,(g.) (;)\nu(g)méc(f)tis(g) at(h)que(gf) flá(g)ti(f)bus(e\'_) (,)\nter(e)ram(c) bap(d)tí(f)zans(ef) ró(g)ri(f)bus.(e.) (::)\n\n3. Iam(e) noc(c)tis(d) um(f)bra(ef) lín(g)qui(f)tur,(e\'_) (,)\npo(e)lum(c) ca(d)lí(f)go(ef) dé(g)se(g)rit,(g.) (;)\nty(g)pús(f)que(g) Chris(h)ti,(gf) lú(g)ci(f)fer(e\'_) (,)\ndi(e)em(c) so(d)pí(f)tum(ef) sú(g)sci(f)tat.(e.) (::)\n\n4. Di(e)es(c) di(d)é(f)rum(ef) tu,(g) De(f)us,(e\'_) (,)\nlu(e)cís(c)que(d) lu(f)men(ef) ip(g)se(g) es,(g.) (;)\nU(g)num(f) pot(g)ens(h) per(gf) óm(g)ni(f)a,(e\'_) (,)\npot(e)ens(c) in(d) u(f)num(ef) Trí(g)ni(f)tas.(e.) (::)\n\n5. Te(e) nunc,(c) Sal(d)vá(f)tor,(ef) quǽ(g)su(f)mus(e\'_) (,)\nti(e)bí(c)que(d) ge(f)nu(ef) fléc(g)ti(g)mus,(g.) (;)\nPa(g)trem(f) cum(g) Sanc(h)to(gf) Spí(g)ri(f)tu(e\'_) (,)\nto(e)tis(c) lau(d)dán(f)tes(ef) vó(g)ci(f)bus.(e.) (::)\n', NULL, 'Feria VI ad Laudes Matutinas', 0, NULL),
(16749, NULL, 'Solesmes 1983', 'Adesto rerum conditor', 1, 'hy', '2', NULL, 'carolus7', NULL, NULL, '\"(f3)Ad(f)\\u00e9s(e)to,(f) re(h)rum(i) c\\u00f3n(h)di(g)tor,(f\'_) (,)\\r\\npa(i)t\\u00e9r(i)n\\u00e6(h) lu(i)cis(j) gl\\u00f3(h)ri(g)a,(f.) (;)\\r\\ncu(f)ius(f) a(g)m\\u00f3(e)ta(c) gr\\u00e1(e)ti(f)a(f\'_) (,)\\r\\nnos(f)tra(e) pa(f)v\\u00e9s(h)cunt(i) p\\u00e9c(h)to(g)ra,(f.) (::)\"', '2. Tu(f)ó(e)que(f) ple(h)na(i) Spí(h)ri(g)tu,(f\'_) (,)\nse(i)cum(i) De(h)um(i) ges(j)tán(h)ti(g)a,(f.) (;)\nnil(f) ra(f)pi(g)én(e)tis(c) pér(e)fi(f)di(f\'_) (,)\ndi(f)ris(e) pa(f)tés(h)cant(i) fráu(h)di(g)bus,(f.) (::)\n\n3. Ut(f) in(e)ter(f) ac(h)tus(i) sǽ(h)cu(g)li,(f\'_) (,)\nvi(i)tæ(i) quos(h) u(i)sus(j) éx(h)i(g)git,(f.) (;)\nom(f)ni(f) ca(g)rén(e)tes(c) crí(e)mi(f)ne(f\'_) (,)\ntu(f)is(e) vi(f)vá(h)mus(i) lé(h)gi(g)bus.(f.) (::)\n\n4. Sit,(f) Chris(e)te,(f) rex(h) pi(i)ís(h)si(g)me,(f\'_) (,)\nti(i)bi(i) Pa(h)trí(i)que(j) gló(h)ri(g)a(f.) (;)\ncum(f) Spí(f)ri(g)tu(e) Pa(c)rá(e)cli(f)to,(f\'_) (,)\nin(f) sem(e)pi(f)tér(h)na(i) sǽ(h)cu(g)la.(f.) (::)\n', NULL, 'ad Oficcium lectionis (diurno tempore)', 0, NULL),
