(17944, NULL, NULL, 'Vir celse forma fulgida', 1, 'hy', '4', NULL, 'caniato', NULL, NULL, '\"annotation: Hymnus;\\r\\nannotation: IV;\\r\\n%%\\r\\n(c4)Vir(f) cel(fe)se,(d) for(e)ma(g) ful(gh)gi(f)da(e) (,) vir(g)tu(h)tis,(g) hym(hiwji)num(g) su(g)sci(f)pe,(h) (;) qui(h) iu(h)re(g) dum(hiwji) te(gf) pr\\u00e6(h)di(h)cat,(dewfe) (,) De(e)i(c) ca(e)nit(gfh) ma(gf)gna(g)li(fe)a.(f) (::) (z)\\r\\n\\r\\n2. Qui(f) sem(fe)pi(d)ter(e)nus(g) Pon(gh)ti(f)fex(e) (,) stir(g)pem(h) De(g)o(hiwji) mor(g)ta(g)li(f)um(h) (;) re(h)vin(h)xit,(g) at(hiwji)que(gf) red(h)di(h)dit(dewfe) (,) pa(e)ci(c) no(e)vo(gfh) nos(gf) f\\u0153(g)de(fe)re.(f) (::) (z)\\r\\n\\r\\n3. Te(f) fe(fe)cit(d) ip(e)se(g) pro(gh)vi(f)dus(e) (,) su(g)is(h) mi(g)ni(hiwji)strum(g) mu(g)ne(f)ris,(h) (;) Pa(h)tri(h) da(g)tu(hiwji)rum(gf) glo(h)ri(h)am(dewfe) (,) e(e)ius(c)que(e) vi(gfh)tam(gf) ple(g)bi(fe)bus.(f) (::) (Z)\\r\\n\\r\\n[alt:Pro papa:] 4.Tu(f) Pe(fe)tr<i>i</i> o(d)vi(e)le(g) c\\u00e6(gh)li(f)tus(e) (,) sum(g)ptis(h) re(g)ge(hiwji)bas(g) cla(g)vi(f)bus,(h)(;) gre(h)gem(h)que(g) ver(hiwji)bo(gf) gra(h)ti(h)\\u00e6,(dewfe) (,) pu(e)ris(c) fo(e)ve(gfh)as(gf) a(g)cti(fe)bus.(f) (::) (z)\\r\\n\\r\\n\\r\\n[alt:Pro episcopo:] 4. Vir(f)tu(fe)te(d) fac(e)tus(g) di(gh)ti(f)or(e) (,) te(g) con(h)se(g)cran(hiwji)tis(g) Spi(g)ri(f)tus,(h) (;) pr\\u00e6(h)sul,(h) sa(g)lu(hiwji)tis(gf) pin(h)gui(h)a(dewfe) (,) tu(e) tra(c)di(e)dis(gfh)ti(gf) pa(g)bu(fe)la(f) (::) (z)\\r\\n\\r\\n\\r\\n[alt:Pro presbytero:] 4. Re(f)ga(fe)lis(d) hu(e)ius(g) cul(gh)mi(f)nis(e) (,) a(g)dep(h)tus(g) al(hiwji)ti(g)tu(g)di(f)nem,(h) (;) ver(h)bo(h) fu(g)i(hiwji)st<i>i</i> et(gf) mo(h)ri(h)bus(dewfe) (,) doc(e)tor,(c) sa(e)cer(gfh)dos,(gf) hos(g)ti(fe)a.(f) (::) (z)\\r\\n\\r\\n5. Lo(f)ca(fe)tus(d) in(e) c\\u00e6(g)le(gh)sti(f)bus,(e) (,) san(g)ct\\u00e6(h) me(g)men(hiwji)t<i>o</i> Ec(g)cle(g)si(f)\\u00e6,(h) (;) o(h)ves(h) ut(g) om(hiwji)nes(gf) pas(h)cu(h)a(dewfe) (,) Chri(e)sti(c) pe(e)tant(gfh) fe(gf)li(g)ci(fe)a.(f) (::) (z)\\r\\n\\r\\n6. Sit